using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata: {personInfo.Type.Name}");

// Round-trip to prove it works:
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-tripped: {p}");

// 2) Probe without throwing — TryGetTypeInfo returns false instead of throwing.
//    Use a second options instance with NO resolver so lookup will fail.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? maybe))
{
    Console.WriteLine($"Found metadata (unexpected): {maybe!.Type.Name}");
}
else
{
    Console.WriteLine("No metadata for Person — and no exception was thrown.");
}

// Also show the success path of TryGetTypeInfo:
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"TryGetTypeInfo succeeded: {found!.Type.Name}");
}

public record Person(string Name, int Age);

